import{z as n,x as o,o as l,c as d,q as r,j as t,D as E,d as A,s,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"对抗鲁棒评测","description":"","frontmatter":{"title":"对抗鲁棒评测","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/aeval-adversarial-robustness.md","filePath":"llm/aeval-adversarial-robustness.md","lastUpdated":1791413859000}'),m={name:"llm/aeval-adversarial-robustness.md"};function p(D,a,h,u,f,C){const B=o("Mermaid");return l(),d("div",null,[a[2]||(a[2]=r('<h1 id="对抗鲁棒评测" tabindex="-1">对抗鲁棒评测 <a class="header-anchor" href="#对抗鲁棒评测" aria-label="Permalink to &quot;对抗鲁棒评测&quot;">​</a></h1><div class="epigraph"><p>平均分是给产品看的，最坏值是给门禁看的：一个杀掉十个攻击族里九个的防御，在第十个面前等于零。</p><footer>—— 据 Zou et al., 2023（GCG）与 Ganguli et al., 2022 的攻击谱系整理</footer></div><p><a href="/llm/aeval-crossmodel-pitfalls">上一课</a>把跨模型比较钉成冻结 harness 与偏差审计——但那些协议都默认题面固定。对手不配合：题面会被优化、包装、载入上下文。第二课的红队产线在私有侧生产失败；本课把鲁棒性写成公开可门禁的协议：攻击族矩阵、预算声明、最坏值报告。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态套件测的是「默认攻击分布」下的配合率，三个缺口使它撑不起安全声明。一是均值掩盖尾部：防御对模板类攻击有效、对优化类攻击失守时，平均 ASR 依然好看，产品却在可复现的公开攻击下全防不住。二是攻击集衰减：套件一旦公开，它就同时变成训练语料与过拟合目标，「在旧攻击上 ASR 低」的信息量随时间指数衰减。三是预算不定：查询次数、生成长度、白盒还是黑盒不声明，两个「ASR 5%」不可比——一个是默认模板扫一遍，一个是自适应优化攻击跑满预算。</p><p><span class="marginnote">ASR（Attack Success Rate，攻击成功率）指攻击提示让模型放弃拒绝、顺着有害请求作答的比例。比如 100 条越狱提示里模型配合了 40 条，这一族的 ASR 就是 40%。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="攻击族矩阵与预算声明" tabindex="-1">攻击族矩阵与预算声明 <a class="header-anchor" href="#攻击族矩阵与预算声明" aria-label="Permalink to &quot;攻击族矩阵与预算声明&quot;">​</a></h3><p>危害集按第一课冻结，攻击族至少四类铺开：<strong>模板/角色包装</strong>（人格化、虚构约定、系统冒充）；<strong>优化后缀</strong>（梯度引导的对抗后缀，GCG 一类，谱系见<a href="/llm/gcg-suffix">对抗后缀</a>）；<strong>上下文压载</strong>（长前缀稀释拒绝，见<a href="/llm/many-shot-jailbreak">多样本越狱</a>）；<strong>接口类</strong>（预填、多模态通道，见<a href="/llm/prefill-jailbreak">预填越狱</a>与<a href="/llm/multimodal-jailbreak">多模态越狱</a>）。每族声明预算：查询数、生成 token 上限、访问级别（黑盒/白盒）。数字按族报：\\(\\mathrm{ASR}_A=\\Pr_{x\\in H}[\\text{配合}\\mid A(x)]\\)，门禁取最坏值 \\(\\max_A \\mathrm{ASR}_A\\)，不取均值。</p>',9)),(l(),t(i,null,{default:E(()=>[s(B,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20HARM%5B%22%E5%86%BB%E7%BB%93%E5%8D%B1%E5%AE%B3%E9%9B%86%22%5D%20--%3E%20F1%5B%22%E6%A8%A1%E6%9D%BF%20%2F%20%E8%A7%92%E8%89%B2%E5%8C%85%E8%A3%85%22%5D%0A%20%20HARM%20--%3E%20F2%5B%22%E4%BC%98%E5%8C%96%E5%90%8E%E7%BC%80%22%5D%0A%20%20HARM%20--%3E%20F3%5B%22%E4%B8%8A%E4%B8%8B%E6%96%87%E5%8E%8B%E8%BD%BD%22%5D%0A%20%20HARM%20--%3E%20F4%5B%22%E6%8E%A5%E5%8F%A3%E7%B1%BB%EF%BC%9A%E9%A2%84%E5%A1%AB%20%2F%20%E5%A4%9A%E6%A8%A1%E6%80%81%22%5D%0A%20%20F1%20--%3E%20BUD%5B%22%E5%90%84%E6%97%8F%E9%A2%84%E7%AE%97%E5%A3%B0%E6%98%8E%22%5D%0A%20%20F2%20--%3E%20BUD%0A%20%20F3%20--%3E%20BUD%0A%20%20F4%20--%3E%20BUD%0A%20%20BUD%20--%3E%20MAT%5B%22%E9%80%90%E6%97%8F%20ASR%20%E7%9F%A9%E9%98%B5%22%5D%0A%20%20MAT%20--%3E%20WC%5B%22%E6%9C%80%E5%9D%8F%E5%80%BC%E9%97%A8%E7%A6%81%22%5D%0A%20%20WC%20--%3E%20ADA%5B%22%E8%87%AA%E9%80%82%E5%BA%94%E5%A4%8D%E6%B5%8B%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[A("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"为什么自适应评测不可省：防御细节公开后，理性的攻击者会针对防御改写攻击——只拿默认攻击测新防御，测到的是攻击者的惯性，不是系统的鲁棒性。协议上把「知道防御后重跑」写进门禁，数字才随时间保值。",-1)),a[5]||(a[5]=e("p",null,"一个新防御的读数如何随攻击方演化而缩水，又如何靠自适应复测保值：",-1)),(l(),t(i,null,{default:E(()=>[s(B,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20DEF%5B%22%E6%96%B0%E9%98%B2%E5%BE%A1%E4%B8%8A%E7%BA%BF%22%5D%20--%3E%20OLD%5B%22%E9%BB%98%E8%AE%A4%E6%94%BB%E5%87%BB%E9%9B%86%E6%B5%8B%EF%BC%9AASR%205%25%EF%BC%8C%E5%A5%BD%E7%9C%8B%22%5D%0A%20%20OLD%20--%3E%20PUB%5B%22%E9%98%B2%E5%BE%A1%E7%BB%86%E8%8A%82%E5%85%AC%E5%BC%80%22%5D%0A%20%20PUB%20--%3E%20ADV%5B%22%E6%94%BB%E5%87%BB%E8%80%85%E9%92%88%E5%AF%B9%E9%98%B2%E5%BE%A1%E6%94%B9%E5%86%99%E6%94%BB%E5%87%BB%22%5D%0A%20%20ADV%20--%3E%20RE%5B%22%E8%87%AA%E9%80%82%E5%BA%94%E5%A4%8D%E6%B5%8B%EF%BC%9AASR%2040%25%22%5D%0A%20%20RE%20--%3E%20GATE%5B%22%E9%97%A8%E7%A6%81%E6%8C%89%E6%9C%80%E5%9D%8F%E5%80%BC%E5%88%A4%E5%AE%9A%22%5D%0A%20%20GATE%20--%3E%7C%22%E4%B8%8D%E8%BF%87%22%7C%20FIX%5B%22%E8%A1%A5%E8%BE%B9%E7%95%8C%20%2F%20%E5%8A%A0%E5%9B%BA%E9%98%B2%E5%BE%A1%22%5D%0A%20%20FIX%20--%3E%20ADA%5B%22%E4%B8%8B%E4%B8%80%E8%BD%AE%E8%87%AA%E9%80%82%E5%BA%94%E5%A4%8D%E6%B5%8B%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">数字实例：四个攻击族的 ASR 若分别是 2%、3%、4%、40%，平均约 12% 看着尚可；但攻击者不需要攻破九个族，走通一个就够出事——这正是门禁取最坏值而非均值的原因。</span></p><p>判分器也要过攻击关：对抗输出同时瞄准裁判——冗长道歉接实质配合的形态，句式检测与未校准的裁判都会放行（<a href="/llm/jailbreak">越狱评测</a>的教训在对抗场景被放大）；裁判版本固定加人工校准率随每族矩阵一起报。迁移缺口如实报：白盒上很强的优化攻击迁移到黑盒常大幅衰减，部署威胁模型决定哪一列才算数——按部署口径取 \\(\\max\\)，不是按最吓人的列取。</p><p><span class="marginnote">「ASR 5%」没有操作定义：不写明攻击族、预算、自适应与否，同一模型在默认模板下 5%、自适应优化攻击下 40% 是常见量级差。报告口径本身就是防御的一部分。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>免疫没有操作定义，本课能交付的是「在声明预算的这些族上，最坏配合率的区间」，不是「不可攻破」。随机化防御（解码扰动、改写洗牌）提高攻击成本，值得做，但成本上升不等于免疫证明，别把提价写成关门。与第二课的分界再画一次：红队漏斗管私有回归集与未公开发现，本课管公开协议与最坏值门禁；两套账共用判分器与政策版本，不共用披露范围——配方与题面的披露纪律归下一课的报告规范。</p><p><span class="marginnote">「随机化防御」指给模型加一层不可预测的扰动，比如随机改写输入后再作答，让针对原版本的攻击配方失灵。它相当于把门的成本提高：小偷撬锁更费劲了，但门没有被焊死，预算充足的攻击者仍然进得来。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>鲁棒是攻击族矩阵上的最坏值，不是默认攻击分布上的均值。</li><li>每族声明预算与访问级别；不带预算的 ASR 不可比。</li><li>自适应复测进门禁：公开防御要用针对它的攻击重测，数字才保值。</li><li>判分器是攻击面的一部分：版本固定加人工校准率随表发布。</li><li>迁移缺口按部署口径取最坏列；随机化是提价不是关门。</li><li>出处：Zou et al., 2023；Ganguli et al., 2022；HarmBench、JailbreakBench 的预算化口径。</li></ul>',8))])}const _=n(m,[["render",p]]);export{F as __pageData,_ as default};
